-- Lion Patrol v2 — Karim feedback (Oct 25, 2026). Re-runnable; touches patrol_ objects only; never deletes incidents.
-- 1. Patrol start/end are daily-log entries, not incidents: "Patrol & Shift" leaves the incident categories.
-- 4. Per-category form config (patrol_categories.field_config): which standard sections and
--    category-specific fields (stored in patrol_incidents.extra) each category shows.
-- 5. Shift notes / relief-handoff / post check / checkpoint note become "Shift Log" daily-log (DAR) types.
begin;

-- Defaults for new orgs (same JSON as 20261024000500_patrol_seed.sql, regenerated by scripts/gen-seed-sql.mjs).
create or replace function public.patrol_default_categories()
returns jsonb language sql immutable set search_path = public as $seed$
  select '[{"name":"Shift Log","color":"#C9A23F","icon":"shield","use_for":"dar","default_severity":"low","required_fields":[],"field_config":{"sections":[],"extra":[]},"subtypes":["Shift notes","Relief / handoff","Post check","Checkpoint note"]},{"name":"Access & Doors","color":"#4F7CC4","icon":"door","use_for":"both","default_severity":"low","required_fields":[],"field_config":{"sections":["damage"],"extra":[{"key":"door","label":"Door / gate","type":"text"},{"key":"action","label":"Action taken","type":"select","options":["Secured","Left as found","Reported to client"]},{"key":"client_notified","label":"Client notified","type":"yesno"}]},"subtypes":["Door/gate found open","Door/gate unsecured","Lock-up completed","Unlock","Key/fob issue"]},{"name":"Alarm Response","color":"#C66B3D","icon":"bell","use_for":"both","default_severity":"medium","required_fields":[],"field_config":{"sections":["police","ems"],"extra":[{"key":"zone","label":"Zone / panel","type":"text"},{"key":"cause","label":"Cause","type":"select","options":["Unknown","False / accidental","Weather","Intrusion","Equipment fault"]},{"key":"monitoring_contacted","label":"Monitoring company contacted","type":"yesno"}]},"subtypes":["Intrusion alarm","Fire alarm panel","Panic alarm","False alarm","Alarm reset"]},{"name":"Suspicious Activity","color":"#C98A2E","icon":"eye","use_for":"both","default_severity":"medium","required_fields":[],"field_config":{"sections":["people","vehicles","police"],"extra":[]},"subtypes":["Suspicious person","Suspicious vehicle","Loitering","Suspicious package"]},{"name":"Trespass & Removal","color":"#B85C7A","icon":"user-x","use_for":"incident","default_severity":"medium","required_fields":["people"],"field_config":{"sections":["people","vehicles","police"],"extra":[{"key":"prior_warning","label":"Prior warning on file","type":"yesno"}]},"subtypes":["Trespass warning issued","Person removed","Trespass notice served","Returned after warning"]},{"name":"Theft & Shoplifting","color":"#C0504D","icon":"bag","use_for":"incident","default_severity":"high","required_fields":["people","property_damage"],"field_config":{"sections":["people","vehicles","police","damage"],"extra":[{"key":"items","label":"Items taken","type":"text"},{"key":"recovered","label":"Recovered","type":"select","options":["Not recovered","Partially","Fully"]}]},"subtypes":["Shoplifting","Theft from vehicle","Package theft","Burglary","Attempted theft"]},{"name":"Vandalism, Graffiti & Damage","color":"#8467B5","icon":"spray","use_for":"incident","default_severity":"medium","required_fields":["property_damage","photos"],"field_config":{"sections":["people","vehicles","police","damage"],"extra":[]},"subtypes":["Graffiti","Broken window/glass","Property damage","Vehicle damage"]},{"name":"Disturbance & Noise","color":"#5F6BC2","icon":"volume","use_for":"both","default_severity":"medium","required_fields":["people"],"field_config":{"sections":["people","vehicles","police","ems","injury"],"extra":[]},"subtypes":["Noise complaint","Verbal dispute","Fight/assault","Intoxicated person"]},{"name":"Medical & Injury","color":"#C0504D","icon":"medical","use_for":"incident","default_severity":"high","required_fields":["injury","people"],"field_config":{"sections":["people","ems","injury"],"extra":[]},"subtypes":["Injury","Illness","Fall","Overdose suspected","EMS requested"]},{"name":"Fire, Safety & Hazard","color":"#C66B3D","icon":"flame","use_for":"both","default_severity":"high","required_fields":["photos"],"field_config":{"sections":["ems","injury","damage"],"extra":[{"key":"area_secured","label":"Area cordoned off","type":"yesno"},{"key":"reported_to","label":"Reported to","type":"text"}]},"subtypes":["Smoke/fire","Spill","Trip hazard","Gas odor","Blocked exit"]},{"name":"Maintenance & Facility","color":"#3F94B0","icon":"wrench","use_for":"both","default_severity":"low","required_fields":[],"field_config":{"sections":["damage"],"extra":[{"key":"exact_location","label":"Exact location","type":"text"},{"key":"hazard","label":"Safety hazard","type":"yesno"},{"key":"work_order","label":"Work order / ticket #","type":"text"},{"key":"reported_to","label":"Reported to","type":"text"}]},"subtypes":["Lights out","Water leak","Elevator issue","HVAC issue","Broken fixture"]},{"name":"Parking & Vehicles","color":"#4F7CC4","icon":"car","use_for":"both","default_severity":"low","required_fields":["vehicles"],"field_config":{"sections":["vehicles"],"extra":[{"key":"tow_company","label":"Tow company","type":"text"}]},"subtypes":["Parking violation","Tow requested","Abandoned vehicle","Blocked fire lane"]},{"name":"Police, Fire & EMS Contact","color":"#5F6BC2","icon":"siren","use_for":"incident","default_severity":"high","required_fields":["police"],"field_config":{"sections":["people","vehicles","police","ems","injury"],"extra":[]},"subtypes":["Police called","Police on site","Fire dept on site","EMS on site"]},{"name":"Client / Resident Request","color":"#3E9C8F","icon":"user","use_for":"both","default_severity":"low","required_fields":[],"field_config":{"sections":[],"extra":[{"key":"requester","label":"Requested by","type":"text"},{"key":"request","label":"Request","type":"text"},{"key":"action_taken","label":"Action taken","type":"text"}]},"subtypes":["Escort","Lockout assist","Information","Complaint"]},{"name":"Package & Delivery","color":"#C98A2E","icon":"package","use_for":"both","default_severity":"low","required_fields":[],"field_config":{"sections":[],"extra":[{"key":"carrier","label":"Carrier","type":"text"},{"key":"recipient","label":"Recipient / unit","type":"text"},{"key":"disposition","label":"Disposition","type":"select","options":["Delivered to recipient","Held at desk","Left at location","Returned to carrier"]}]},"subtypes":["Delivery received","Package left unsecured","Delivery issue"]},{"name":"Welfare Check (Unhoused Persons)","color":"#3E9C8F","icon":"heart","use_for":"both","default_severity":"low","required_fields":[],"field_config":{"sections":["people","ems"],"extra":[{"key":"resources","label":"Resources offered","type":"text"},{"key":"outcome","label":"Outcome","type":"select","options":["Relocated","Declined","Referred to services","EMS transported"]}]},"subtypes":["Welfare check","Encampment observed","Resources offered","Asked to relocate"]},{"name":"Drug Activity / Paraphernalia","color":"#8467B5","icon":"pill","use_for":"incident","default_severity":"medium","required_fields":["photos"],"field_config":{"sections":["people","police"],"extra":[{"key":"disposal","label":"Paraphernalia disposal","type":"text"}]},"subtypes":["Suspected drug activity","Needles/paraphernalia found"]},{"name":"Animal","color":"#4E9F5D","icon":"paw","use_for":"both","default_severity":"low","required_fields":[],"field_config":{"sections":[],"extra":[{"key":"animal","label":"Animal description","type":"text"},{"key":"animal_control","label":"Animal control called","type":"yesno"}]},"subtypes":["Stray animal","Aggressive animal","Animal control called"]},{"name":"Lost & Found","color":"#3F94B0","icon":"search","use_for":"both","default_severity":"low","required_fields":[],"field_config":{"sections":[],"extra":[{"key":"item","label":"Item description","type":"text"},{"key":"owner","label":"Owner (if known)","type":"text"},{"key":"disposition","label":"Disposition","type":"select","options":["Holding at desk","Returned to owner","Turned over to police","Turned over to client"]}]},"subtypes":["Item found","Item reported lost","Item returned"]},{"name":"Weather","color":"#64748B","icon":"cloud","use_for":"both","default_severity":"low","required_fields":[],"field_config":{"sections":["damage"],"extra":[{"key":"conditions","label":"Conditions","type":"text"},{"key":"impact","label":"Impact on site","type":"text"},{"key":"action_taken","label":"Action taken","type":"text"}]},"subtypes":["Storm damage","Ice/snow hazard","Flooding","Power outage"]},{"name":"Retail Operations","color":"#C9A23F","icon":"store","use_for":"dar","default_severity":"low","required_fields":[],"field_config":{"sections":[],"extra":[]},"subtypes":["Store open check","Store close check","Cash/vault escort","Customer assist"]},{"name":"Residential (Apartments)","color":"#4E9F5D","icon":"building","use_for":"dar","default_severity":"low","required_fields":[],"field_config":{"sections":[],"extra":[]},"subtypes":["Amenity check (pool/gym)","Mailroom check","Unit door open","Move-in/out observed"]},{"name":"Safety Equipment","color":"#C66B3D","icon":"extinguisher","use_for":"both","default_severity":"low","required_fields":[],"field_config":{"sections":[],"extra":[{"key":"equipment","label":"Equipment / location","type":"text"},{"key":"work_order","label":"Work order / ticket #","type":"text"}]},"subtypes":["Fire extinguisher check","Exit sign out","AED check","Camera not working"]},{"name":"Other","color":"#64748B","icon":"note","use_for":"both","default_severity":"low","required_fields":[],"field_config":{"sections":["people","vehicles","police","ems","injury","damage"],"extra":[]},"subtypes":["General observation","Other"]}]'::jsonb
$seed$;

-- "Shift Log" (daily log only) for every existing org, listed first among log categories.
insert into public.patrol_categories (org_id, name, color, icon, sort, required_fields, default_severity, use_for)
select o.id, 'Shift Log', '#C9A23F', 'shield', -1, '{}', 'low', 'dar'
  from public.patrol_orgs o
 where not exists (select 1 from public.patrol_categories c where c.org_id = o.id and lower(c.name) = 'shift log');

insert into public.patrol_subtypes (org_id, category_id, name, sort)
select c.org_id, c.id, s.name, s.ord - 1
  from public.patrol_categories c
 cross join unnest(array['Shift notes', 'Relief / handoff', 'Post check', 'Checkpoint note']) with ordinality as s(name, ord)
 where lower(c.name) = 'shift log'
on conflict do nothing;

-- "Patrol & Shift": delete subtypes/categories nothing references; hide the rest (history stays intact).
delete from public.patrol_subtypes s
 using public.patrol_categories c
 where s.category_id = c.id and lower(c.name) = 'patrol & shift'
   and not exists (select 1 from public.patrol_incidents i where i.subtype_id = s.id)
   and not exists (select 1 from public.patrol_dar_entries e where e.subtype_id = s.id);

update public.patrol_subtypes s set hidden = true
  from public.patrol_categories c
 where s.category_id = c.id and lower(c.name) = 'patrol & shift' and not s.hidden;

delete from public.patrol_categories c
 where lower(c.name) = 'patrol & shift'
   and not exists (select 1 from public.patrol_incidents i where i.category_id = c.id)
   and not exists (select 1 from public.patrol_dar_entries e where e.category_id = c.id)
   and not exists (select 1 from public.patrol_subtypes s where s.category_id = c.id);

update public.patrol_categories set hidden = true
 where lower(name) = 'patrol & shift' and not hidden;

-- Per-category field config. NULL = custom category (client shows every standard section).
alter table public.patrol_categories add column if not exists field_config jsonb;

update public.patrol_categories c set field_config = d->'field_config'
  from jsonb_array_elements(public.patrol_default_categories()) d
 where lower(c.name) = lower(d->>'name') and c.field_config is distinct from d->'field_config';

-- New orgs get field_config too (same as 20261024000500 plus field_config).
create or replace function public.patrol_seed_categories_internal(p_org uuid)
returns integer language plpgsql security definer set search_path = public as $$
declare
  c jsonb; s text; v_cat uuid; v_added integer := 0; v_sort integer; v_sub_sort integer;
  v_max integer;
begin
  select coalesce(max(sort), -1) into v_max from public.patrol_categories where org_id = p_org;
  v_sort := 0;
  for c in select * from jsonb_array_elements(public.patrol_default_categories()) loop
    select id into v_cat from public.patrol_categories where org_id = p_org and lower(name) = lower(c->>'name');
    if v_cat is null then
      insert into public.patrol_categories (org_id, name, color, icon, sort, required_fields, default_severity, use_for, field_config)
      values (p_org, c->>'name', c->>'color', c->>'icon', v_max + 1 + v_sort,
              array(select jsonb_array_elements_text(c->'required_fields')),
              (c->>'default_severity')::public.patrol_severity, c->>'use_for', c->'field_config')
      returning id into v_cat;
      v_added := v_added + 1;
    end if;
    v_sub_sort := 0;
    for s in select * from jsonb_array_elements_text(c->'subtypes') loop
      insert into public.patrol_subtypes (org_id, category_id, name, sort)
      values (p_org, v_cat, s, v_sub_sort)
      on conflict do nothing;
      v_sub_sort := v_sub_sort + 1;
    end loop;
    v_sort := v_sort + 1;
  end loop;
  return v_added;
end $$;
revoke all on function public.patrol_seed_categories_internal(uuid) from public, anon, authenticated;

commit;
